import sys

MOD = 998244353

def modinv(x):
    return pow(x, MOD - 2, MOD)

def main():
    n, k, l = map(int, sys.stdin.readline().split())
    if k == 0:
        print(l % MOD)
        return

    maxN = 2 * n
    fact = [1] * (maxN + 1)
    invfact = [1] * (maxN + 1)
    for i in range(1, maxN + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[maxN] = modinv(fact[maxN])
    for i in range(maxN, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

    inv2 = (MOD + 1) // 2
    inv4 = modinv(4)

    ans = 0
    for t in range(k, n + 1):
        c = comb(n, t)
        if c == 0:
            continue
        if t == 0:
            continue
        invt = modinv(t)
        invt2 = invt * invt % MOD
        term = c * invt2 % MOD
        term = term * inv4 % MOD
        ans = (ans + term) % MOD

    ans = ans * (l % MOD) % MOD
    print(ans)

if __name__ == "__main__":
    main()

